SELECT * FROM `flyways.uni_track_provider.fused_plots_aws` WHERE DATE(position_timestamp) = '2026-09-16' AND position_timestamp >= TIMESTAMP('2026-09-16 05:00:00') AND position_timestamp < TIMESTAMP('2026-09-16 06:00:00') AND latitude BETWEEN 48.6 AND 49.8 AND longitude BETWEEN -123.775 AND -122.575
